insert into rubric_criteria (role_code, sort, name, description, weight) values ('SPM', 3, $q$Owned Miss$q$, $q$The miss traces to a decision the candidate made or owned, not a vendor's or a colleague's error. The CV names the root cause, shows the candidate wrote it up for others, and shows that the write-up changed how the team or company works afterward (a new pre-qualification step, a new review practice). Score high only when the cause, the record and the changed practice are all visible. An honest post-mortem with no change afterward caps at mid.$q$, 25)
